/* Production libraries and creative tools. All generation is an explicit queue action. */
let CREATIVE_SCENE=null,CREATIVE_ASSET='all',CREATIVE_SHOT=null;
let DIRECTOR=null,REPAIR=null,PERFORMANCE=null,RECIPE_EDITOR=null,CREATIVE_FORM=null;
const creativePost=async(action,body={})=>{const result=await post('/api/creative',{action,...body});if(result.ok===false&&$('#creative-message')){$('#creative-message').textContent=result.error||'The request could not complete. Your draft is preserved.';$('#creative-message').classList.add('err')}return result};
const creativeClone=value=>JSON.parse(JSON.stringify(value));
const creativeState=()=>S?.creative||{looks:[],bindings:[],recipes:[],assignments:[],runs:[],benchmarks:[],directions:{},pronunciations:{},reviews:[],source_tokens:{},review_tokens:{},phrase_takes:[]};
function creativeMessage(message,bad=false){const el=$('#creative-message');if(el){el.textContent=message;el.classList.toggle('err',bad)}toast(message,bad)}
function creativeModal(title,body,footer,options={}){
 const form={dirty:false,busy:0,allowClose:false};CREATIVE_FORM=form;
 modal(`<div class="dlg-h"><h2>${title}</h2><button class="btn ghost" aria-label="Close creative editor" onclick="closeModal()">✕</button></div><div class="dlg-b" id="creative-dialog">${body}<p id="creative-message" role="status" aria-live="polite"></p></div><div class="dlg-f">${footer}</div>`,{
  className:'creative-dlg',initialFocus:'#creative-dialog input:not([type=file]):not([type=checkbox]),#creative-dialog select,#creative-dialog textarea,#creative-dialog button',...options,
  beforeClose:()=>form.allowClose||(!form.busy&&(options.beforeClose?options.beforeClose():!form.dirty||confirm('Discard unsaved changes?'))),
  onClose:()=>{options.onClose?.();if(CREATIVE_FORM===form)CREATIVE_FORM=null}
 });
 $('#creative-dialog').addEventListener('input',()=>form.dirty=true);$('#creative-dialog').addEventListener('change',()=>form.dirty=true);
}
function closeCreativeSaved(){if(CREATIVE_FORM)CREATIVE_FORM.allowClose=true;return closeModal()}
async function creativeBusy(button,fn){if(button.disabled)return;const form=CREATIVE_FORM;if(form)form.busy++;button.disabled=true;try{return await fn()}catch(e){creativeMessage(e.message,true)}finally{if(form)form.busy--;if(button.isConnected)button.disabled=false}}
function setupCreative(){
 TITLES.library=['Reference library','Version character looks, outfits and scene references.'];
 TITLES.lab=['Generation lab','Choose recipes, compare candidates and review creative runs.'];
 for(const [id,label,after]of[['library','Reference library','cast'],['lab','Generation lab','queue']]){
  const b=document.createElement('button');b.dataset.t=id;b.innerHTML=`<span class="en">${label}</span>`;b.onclick=()=>go(id);$(`#nav [data-t="${after}"]`).after(b);
  const section=document.createElement('section');section.id='t-'+id;section.className='tab';$('main').append(section);
 }
}
function renderCreative(){
 if(!S?.creative)return;
 if(tab==='library')renderReferenceLibrary();
 if(tab==='lab')renderGenerationLab();
 refreshCreativeResults();
}
function openReferenceLibrary(aid){CREATIVE_ASSET=String(aid);delete SIG['creative-library'];go('library')}
function renderReferenceLibrary(){
 const c=creativeState(),scenes=[...new Set(S.shots.map(s=>s.scene))];
 if(!scenes.includes(CREATIVE_SCENE))CREATIVE_SCENE=scenes[0]??'';
 const shots=S.shots.filter(s=>s.scene===CREATIVE_SCENE);
 if(same('creative-library',[CREATIVE_SCENE,CREATIVE_ASSET,c.looks,c.bindings,c.reviews,shots.map(s=>[s.id,s.keyframe_take,s.outdated]),S.assets]))return;
 $('#t-library').innerHTML=`<div class="toolbar"><button class="btn pri" onclick="editReferenceLook()" ${S.assets.length?'':'disabled'}>Save reference collection</button><label for="library-asset">Cast</label><select id="library-asset" class="creative-select" onchange="CREATIVE_ASSET=this.value;renderReferenceLibrary()"><option value="all">All cast</option>${S.assets.map(a=>`<option value="${a.id}" ${CREATIVE_ASSET===String(a.id)?'selected':''}>${esc(a.name)}</option>`).join('')}</select><span class="muted">Saving again creates a new version; scene assignments stay pinned.</span></div>
 <div class="creative-grid">${c.looks.filter(l=>CREATIVE_ASSET==='all'||String(l.asset_id)===CREATIVE_ASSET).map(l=>{const asset=S.assets.find(a=>a.id===l.asset_id);return `<article class="creative-card"><div class="creative-reference-strip">${l.references.map(r=>`<button class="creative-reference" onclick="lb(${jsq(r.url)})" aria-label="Enlarge ${esc(r.label)}"><img src="${esc(r.url)}" alt="${esc(r.label)}"></button>`).join('')}</div><div class="creative-card-body"><span class="eyebrow">${esc(asset?.name||'Archived cast')} · V${l.version}</span><h3>${esc(l.name)}</h3><p>${esc(l.notes||'Approved reference collection')}</p><div class="toolbar"><button class="btn sm" onclick="bindReferenceLook(${jsq(l.id)})">Use in scene</button><button class="btn sm ghost" onclick="editReferenceLook(${l.asset_id},${jsq(l.id)})">New version</button></div></div></article>`}).join('')||`<div class="empty-state"><h2>Build a reusable reference library</h2><p>Save a character outfit, expression set, prop or location as an immutable collection, then choose the version each scene uses.</p><button class="btn" onclick="go('cast')">Open Cast</button></div>`}</div>
 <div class="creative-section-heading"><h2>Scene continuity review</h2><select aria-label="Scene to review" class="creative-select" onchange="CREATIVE_SCENE=this.value;renderReferenceLibrary()">${scenes.map(s=>`<option ${s===CREATIVE_SCENE?'selected':''}>${esc(s)}</option>`).join('')}</select></div>
 <div class="creative-bound">${c.bindings.filter(b=>b.scene===CREATIVE_SCENE).map(b=>{const l=c.looks.find(l=>l.id===b.look_id),a=S.assets.find(a=>a.id===b.asset_id);return l?`<span class="creative-binding"><b>${esc(a?.name)}:</b> ${esc(l.name)} v${l.version} · ${esc(l.references[b.view_index]?.label)} <button class="btn sm ghost" onclick="creativePost('look_bind',{scene:${jsq(b.scene)},asset_id:${b.asset_id},look_id:null})" aria-label="Remove ${esc(a?.name)} scene override">Remove</button></span>`:''}).join('')||'<p class="muted">No pinned reference collections for this scene. Assign a collection above to establish its look.</p>'}</div>
 <div class="creative-review-grid">${shots.map(s=>{const k=take(s.keyframe_take),review=c.reviews.find(r=>r.shot_id===s.id);const refs=c.bindings.filter(b=>b.scene===s.scene).map(b=>c.looks.find(l=>l.id===b.look_id)?.references[b.view_index]).filter(Boolean);return `<article class="creative-card"><div class="creative-card-body"><div class="row"><h3>Shot ${pad(s.seq)}</h3><span class="${review?.current?'ok-t':'muted'}">${review?.current?'✓ Reviewed':review?'Review outdated':'Needs review'}</span></div><div class="creative-compare"><div>${k?`<img src="${k.url}" alt="Selected keyframe for shot ${pad(s.seq)}">`:'<p>No selected keyframe</p>'}</div><div>${refs.map(r=>`<img src="${r.url}" alt="Scene reference: ${esc(r.label)}">`).join('')||'<p class="muted">No pinned scene references</p>'}</div></div>${review?.notes?`<p>${esc(review.notes)}</p>`:''}<div class="toolbar"><button class="btn sm" onclick="jump(${s.id})">Open shot</button><button class="btn sm" ${k?'':'disabled'} onclick="reviewCreativeShot(${s.id})">Mark reviewed…</button></div></div></article>`}).join('')||'<p>Add shots to review a scene.</p>'}</div>`;
}
function lookReferenceOptions(aid,base){const a=S.assets.find(a=>a.id===+aid);const refs=base?.references||[{path:a?.image,label:'Current reference'},...(a?.sheets||[]).map((t,i)=>({path:t.path,label:'Sheet '+(i+1)}))].filter(r=>r.path);return refs.filter((r,i)=>refs.findIndex(x=>x.path===r.path)===i)}
function editReferenceLook(aid,baseId){
 const base=creativeState().looks.find(l=>l.id===baseId);aid=aid||S.assets[0]?.id;if(!aid)return toast('Add a cast entry first.',true);
 let refs=lookReferenceOptions(aid,base);
 creativeModal(base?'New reference collection version':'Save reference collection',`<p class="muted">Capture approved images and the current cast description/LoRA settings. Existing versions and scene assignments are preserved.</p><div class="g2"><div><label class="f" for="look-asset">Cast entry</label><select id="look-asset">${S.assets.map(a=>`<option value="${a.id}" ${a.id===aid?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div><label class="f" for="look-name">Collection name</label><input id="look-name" value="${esc(base?.name||'')}" placeholder="Travelling outfit · dusk"></div></div><label class="f" for="look-notes">Continuity notes</label><textarea id="look-notes" placeholder="Clothing, expression, colors, props and details to preserve">${esc(base?.notes||'')}</textarea><fieldset class="creative-fieldset"><legend>Existing reference images</legend><div id="look-existing"></div></fieldset><label class="f" for="look-files">Additional PNG references</label><input id="look-files" type="file" accept="image/png" multiple>`, '<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" id="look-save">Save new version</button>');
 const show=()=>{$('#look-existing').innerHTML=refs.map((r,i)=>`<label class="creative-reference-option"><input type="checkbox" data-look-ref="${i}" checked><img src="/media/${esc(r.path)}" alt=""><span>${esc(r.label)}</span></label>`).join('')||'<p class="muted">Upload a PNG or add a Cast reference first.</p>'};show();
 $('#look-asset').onchange=()=>{refs=lookReferenceOptions(+$('#look-asset').value);show()};
 $('#look-save').onclick=e=>creativeBusy(e.currentTarget,async()=>{const files=await Promise.all([...$('#look-files').files].map(readFile));const result=await creativePost('look_save',{asset_id:+$('#look-asset').value,name:$('#look-name').value,notes:$('#look-notes').value,references:[...document.querySelectorAll('[data-look-ref]:checked')].map(x=>refs[+x.dataset.lookRef]),files});if(result.ok!==false){closeCreativeSaved();toast('Saved reference collection v'+result.version)}});
}
function bindReferenceLook(id){const l=creativeState().looks.find(l=>l.id===id);if(!l)return;const scenes=[...new Set(S.shots.map(s=>s.scene))];if(!scenes.length)return toast('Add a scene first.',true);
 creativeModal('Choose a scene reference',`<h3>${esc(l.name)} · v${l.version}</h3><label class="f" for="look-scene">Scene</label><select id="look-scene">${scenes.map(s=>`<option ${s===CREATIVE_SCENE?'selected':''}>${esc(s)}</option>`).join('')}</select><label class="f" for="look-view">Reference view for generation</label><select id="look-view">${l.references.map((r,i)=>`<option value="${i}">${esc(r.label)}</option>`).join('')}</select><p class="muted">A scene supports up to three image overrides. Other versions and other scenes keep their assignments.</p>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" id="look-bind">Use this version</button>');
 $('#look-bind').onclick=e=>creativeBusy(e.currentTarget,async()=>{const r=await creativePost('look_bind',{scene:$('#look-scene').value,asset_id:l.asset_id,look_id:l.id,view_index:+$('#look-view').value});if(r.ok!==false){closeCreativeSaved();toast('Scene reference pinned')}});
}
function reviewCreativeShot(sid){const token=creativeState().review_tokens[sid];creativeModal('Record continuity review','<p>Confirm the selected keyframe matches the scene references shown in the library.</p><label class="f" for="review-notes">Review notes (optional)</label><textarea id="review-notes"></textarea>','<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" id="review-save">Mark reviewed</button>');$('#review-save').onclick=e=>creativeBusy(e.currentTarget,async()=>{const r=await creativePost('review',{shot_id:sid,signature:token,notes:$('#review-notes').value});if(r.ok!==false)closeCreativeSaved()})}

// Director: subject placement, a draggable OpenPose-style body skeleton and camera endpoints.
const DIRECTOR_JOINTS=[[.5,.14],[.5,.24],[.39,.25],[.33,.4],[.29,.53],[.61,.25],[.67,.4],[.71,.53],[.44,.53],[.43,.72],[.42,.93],[.56,.53],[.57,.72],[.58,.93],[.47,.12],[.53,.12],[.44,.14],[.56,.14]];
const DIRECTOR_LIMBS=[[1,2],[2,3],[3,4],[1,5],[5,6],[6,7],[1,8],[8,9],[9,10],[1,11],[11,12],[12,13],[1,0],[0,14],[14,16],[0,15],[15,17]];
const DIRECTOR_COLORS=['#ff0000','#ff5500','#ffaa00','#ffff00','#aaff00','#55ff00','#00ff00','#00ff55','#00ffaa','#00ffff','#00aaff','#0055ff','#0000ff','#5500ff','#aa00ff','#ff00ff','#ff00aa','#ff0055'];
function openDirector(sid){
 const shot=S.shots.find(s=>s.id===sid);if(!shot)return;const saved=creativeState().directions[sid]||{};
 DIRECTOR={sid,mode:'layout',dirty:false,busy:false,boxes:creativeClone(saved.boxes||shot.asset_ids.map((id,i)=>({asset_id:id,x:(i+1)/(shot.asset_ids.length+1),y:.55,width:.2,height:.65}))),joints:creativeClone(saved.joints?.length?saved.joints:DIRECTOR_JOINTS),image:null};
 const camera=saved.camera||{start:{x:.5,y:.5,zoom:1},end:{x:.5,y:.5,zoom:1.1}};
 creativeModal('Shot '+pad(shot.seq)+' · Direction',`<p class="muted">Stage the image, drag pose joints and preview a camera move locally. Pose, depth and layout conditioning require a compatible recipe.</p><div class="director-grid"><div><div class="toolbar"><button class="btn sm" onclick="DIRECTOR.mode='layout';drawDirector()">Composition</button><button class="btn sm" onclick="DIRECTOR.mode='pose';drawDirector()">Pose</button><button class="btn sm" onclick="DIRECTOR.mode='camera';drawDirector()">Camera</button><span class="muted" id="director-mode">Drag a subject to place it</span></div><canvas id="director-canvas" width="960" height="540" tabindex="0" aria-label="Shot composition and pose editor"></canvas><p class="sv-help">Drag subjects or joints. Numeric controls below provide keyboard editing. In Camera mode, clicking sets the end-frame center.</p><details><summary>Subject and joint coordinates</summary><div id="director-coordinates"></div></details><div id="director-preview"></div></div><div><label class="f" for="director-subject">Add subject</label><div class="toolbar"><select id="director-subject" class="creative-select">${S.assets.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select><button class="btn sm" onclick="addDirectorSubject()">Add</button></div><div class="g2">${['start','end'].map(key=>`<fieldset class="creative-fieldset"><legend>${key==='start'?'Start frame':'End frame'}</legend>${['x','y','zoom'].map(field=>`<label class="f" for="camera-${key}-${field}">${field==='zoom'?'Zoom':field.toUpperCase()+' center'}</label><input id="camera-${key}-${field}" type="number" min="${field==='zoom'?1:0}" max="${field==='zoom'?4:1}" step="0.05" value="${camera[key][field]}" oninput="DIRECTOR.dirty=true;drawDirector()">`).join('')}</fieldset>`).join('')}</div><label class="f" for="director-notes">Direction notes</label><textarea id="director-notes" oninput="DIRECTOR.dirty=true" placeholder="Framing, eyeline and the action to preserve">${esc(saved.notes||'')}</textarea><label class="check"><input id="director-condition" type="checkbox" ${saved.conditioning?'checked':''} onchange="DIRECTOR.dirty=true"> Send conditioning to generation</label><div class="opts"><label class="check"><input id="director-use-layout" type="checkbox" ${saved.layout?'checked':''} onchange="DIRECTOR.dirty=true"> Composition map (LAYOUT)</label><label class="check"><input id="director-use-pose" type="checkbox" ${saved.pose?'checked':''} onchange="DIRECTOR.dirty=true"> Pose skeleton (POSE)</label></div><label class="f" for="director-depth">Depth PNG (DEPTH, optional)</label><input id="director-depth" type="file" accept="image/png" onchange="DIRECTOR.dirty=true"><label class="check"><input id="director-clear-depth" type="checkbox" onchange="DIRECTOR.dirty=true"> Remove saved depth input</label><p class="sv-help">Conditioning uses explicit POSE, DEPTH and LAYOUT inputs in a selected keyframe recipe. Camera moves affect still-shot assembly and animatics; they do not force a video model's camera trajectory.</p></div></div>`, '<button class="btn" id="director-preview-button">Save & preview camera</button><button class="btn pri" id="director-save">Save direction</button>',{beforeClose:()=>!DIRECTOR?.busy&&(!DIRECTOR?.dirty||confirm('Discard unsaved shot direction?')),onClose:()=>{DIRECTOR=null}});
 const k=take(shot.keyframe_take);if(k){const image=new Image();image.onload=()=>{if(DIRECTOR?.sid===sid){DIRECTOR.image=image;drawDirector()}};image.src=k.url}
 const canvas=$('#director-canvas');let dragging=null;
 const point=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]};
 canvas.onpointerdown=e=>{const [x,y]=point(e);if(DIRECTOR.mode==='camera'){$('#camera-end-x').value=x.toFixed(2);$('#camera-end-y').value=y.toFixed(2);DIRECTOR.dirty=true;drawDirector();return}const items=DIRECTOR.mode==='pose'?DIRECTOR.joints.map(p=>({x:p[0],y:p[1]})):DIRECTOR.boxes;let best=.12;items.forEach((p,i)=>{const d=Math.hypot(p.x-x,p.y-y);if(d<best){best=d;dragging=i}});if(dragging!==null)canvas.setPointerCapture(e.pointerId)};
 canvas.onpointermove=e=>{if(dragging===null)return;let[x,y]=point(e);x=Math.max(0,Math.min(1,x));y=Math.max(0,Math.min(1,y));if(DIRECTOR.mode==='pose')DIRECTOR.joints[dragging]=[x,y];else Object.assign(DIRECTOR.boxes[dragging],{x,y});DIRECTOR.dirty=true;drawDirector()};
 canvas.onpointerup=()=>{dragging=null;directorCoordinates()};canvas.onpointercancel=canvas.onpointerup;
 $('#director-save').onclick=e=>creativeBusy(e.currentTarget,()=>saveDirector(false));$('#director-preview-button').onclick=e=>creativeBusy(e.currentTarget,()=>saveDirector(true));directorCoordinates();drawDirector();
}
function cameraValues(){return Object.fromEntries(['start','end'].map(key=>[key,Object.fromEntries(['x','y','zoom'].map(f=>[f,+$('#camera-'+key+'-'+f).value]))]))}
function drawDirectorOn(canvas,kind,background){const d=DIRECTOR,g=canvas.getContext('2d'),w=canvas.width,h=canvas.height;g.clearRect(0,0,w,h);g.fillStyle=kind==='pose'?'#000':'#f2f4f7';g.fillRect(0,0,w,h);if(background&&d.image)g.drawImage(d.image,0,0,w,h);
 if(kind==='pose'){DIRECTOR_LIMBS.forEach(([a,b],i)=>{g.strokeStyle=DIRECTOR_COLORS[i];g.lineWidth=5;g.beginPath();g.moveTo(d.joints[a][0]*w,d.joints[a][1]*h);g.lineTo(d.joints[b][0]*w,d.joints[b][1]*h);g.stroke()});d.joints.forEach((p,i)=>{g.fillStyle=DIRECTOR_COLORS[i];g.beginPath();g.arc(p[0]*w,p[1]*h,6,0,Math.PI*2);g.fill()})}
 else{d.boxes.forEach((b,i)=>{const a=S.assets.find(a=>a.id===b.asset_id);g.strokeStyle='#2f6fa8';g.fillStyle='rgba(228,238,248,.45)';g.lineWidth=3;g.fillRect((b.x-b.width/2)*w,(b.y-b.height/2)*h,b.width*w,b.height*h);g.strokeRect((b.x-b.width/2)*w,(b.y-b.height/2)*h,b.width*w,b.height*h);g.fillStyle='#1e2229';g.font='20px system-ui';g.fillText(a?.name||'Subject',(b.x-b.width/2)*w+8,(b.y-b.height/2)*h+28)})}
 if(kind==='camera'){const camera=cameraValues();Object.entries(camera).forEach(([key,c])=>{g.strokeStyle=key==='start'?'#2f6fa8':'#c8372d';g.lineWidth=4;g.setLineDash(key==='end'?[10,6]:[]);const cw=w/c.zoom,ch=h/c.zoom,x=Math.max(0,Math.min(w-cw,c.x*w-cw/2)),y=Math.max(0,Math.min(h-ch,c.y*h-ch/2));g.strokeRect(x,y,cw,ch);g.setLineDash([]);g.fillStyle=g.strokeStyle;g.fillText(key==='start'?'Start':'End',x+10,y+24)})}
}
function drawDirector(){if(!DIRECTOR||!$('#director-canvas'))return;drawDirectorOn($('#director-canvas'),DIRECTOR.mode,true);$('#director-mode').textContent=DIRECTOR.mode==='pose'?'Drag joints to pose the character':DIRECTOR.mode==='camera'?'Click to place the end-frame center':'Drag subjects to stage the frame'}
function directorCoordinates(){if(!DIRECTOR)return;$('#director-coordinates').innerHTML=DIRECTOR.boxes.map((b,i)=>`<div class="director-coordinate"><b>${esc(S.assets.find(a=>a.id===b.asset_id)?.name||'Subject')}</b>${['x','y','width','height'].map(f=>`<label>${f}<input type="number" min="0.02" max="1" step=".02" value="${b[f]}" onchange="DIRECTOR.boxes[${i}].${f}=+this.value;DIRECTOR.dirty=true;drawDirector()"></label>`).join('')}<button class="btn sm danger" onclick="DIRECTOR.boxes.splice(${i},1);DIRECTOR.dirty=true;directorCoordinates();drawDirector()">Remove</button></div>`).join('')+`<details><summary>Pose joint coordinates</summary>${DIRECTOR.joints.map((p,i)=>`<div class="director-coordinate"><b>Joint ${i+1}</b>${p.map((v,k)=>`<label>${k?'Y':'X'}<input type="number" min="0" max="1" step=".02" value="${v}" onchange="DIRECTOR.joints[${i}][${k}]=+this.value;DIRECTOR.dirty=true;drawDirector()"></label>`).join('')}</div>`).join('')}</details>`}
function addDirectorSubject(){if(DIRECTOR.boxes.length>=12)return toast('Use at most 12 subjects.',true);DIRECTOR.boxes.push({asset_id:+$('#director-subject').value,x:.5,y:.55,width:.2,height:.6});DIRECTOR.dirty=true;directorCoordinates();drawDirector()}
function directorFile(kind){const canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;drawDirectorOn(canvas,kind,false);return{name:kind+'.png',data:canvas.toDataURL('image/png')}}
async function saveDirector(preview){if(!DIRECTOR)return;DIRECTOR.busy=true;try{const body={shot_id:DIRECTOR.sid,boxes:DIRECTOR.boxes,joints:DIRECTOR.joints,camera:cameraValues(),notes:$('#director-notes').value,conditioning:$('#director-condition').checked,clear_pose:!$('#director-use-pose').checked,clear_layout:!$('#director-use-layout').checked,clear_depth:$('#director-clear-depth').checked};if(!body.clear_pose)body.pose_file=directorFile('pose');if(!body.clear_layout)body.layout_file=directorFile('layout');if($('#director-depth').files[0])body.depth_file=await readFile($('#director-depth').files[0]);const r=await creativePost('direction_save',body);if(r.ok===false)return;DIRECTOR.dirty=false;creativeMessage('Shot direction saved.');if(preview){const p=await creativePost('direction_preview',{shot_id:DIRECTOR.sid});if(p.ok!==false)$('#director-preview').innerHTML=`<video controls src="${esc(p.url)}" aria-label="Camera preview"></video>`}}finally{if(DIRECTOR)DIRECTOR.busy=false}}

// Repair candidates retain their immutable source. Masks use LoadImage's inverse-alpha MASK output.
function openRepair(sid,tid){const shot=S.shots.find(s=>s.id===sid);if(!shot)return;const source=shot.takes.find(t=>t.id===(tid||shot.keyframe_take||shot.clip_take));if(!source)return toast('Generate and select a keyframe or clip first.',true);const image=source.stage==='keyframe',recipes=creativeState().recipes.filter(r=>r.purpose===(image?'image_repair':'video_repair'));
 REPAIR={sid,tid:source.id,image,token:creativeState().source_tokens[source.id],dirty:false,busy:false,canvas:null};
 creativeModal('Shot '+pad(shot.seq)+' · '+(image?'Repair keyframe':'Retake video interval'),`<p class="muted">${image?'Paint the area to replace. Outside the mask, the source image is composited back unchanged.':'Choose a short interval to regenerate between source boundary frames. The rest of the source clip is retained; review the joins before selecting.'}</p><label class="f" for="repair-source">Source take</label><select id="repair-source" onchange="changeRepairSource(${sid},+this.value)">${shot.takes.filter(t=>['keyframe','animate','continue','lipsync','upscale'].includes(t.stage)).map(t=>`<option value="${t.id}" ${t.id===source.id?'selected':''}>${esc(t.stage)} · take ${t.id}</option>`).join('')}</select>${image?`<div class="repair-stage"><img id="repair-image" src="${esc(source.url)}" alt="Repair source"><canvas id="repair-mask" aria-label="Paint repair mask" tabindex="0"></canvas></div><div class="toolbar"><label for="repair-brush">Brush</label><input id="repair-brush" type="range" min="4" max="160" value="40"><button class="btn sm" onclick="clearRepairMask()">Clear mask</button><button class="btn sm" onclick="fillRepairMask()">Select whole image</button></div><p class="sv-help">White overlay marks the editable area. You can also upload a mask PNG whose transparent pixels identify the repair area.</p><label class="f" for="repair-mask-file">Replacement mask PNG (optional)</label><input id="repair-mask-file" type="file" accept="image/png" onchange="REPAIR.dirty=true">`:`<video id="repair-video" controls src="${esc(source.url)}" aria-label="Original clip"></video><div class="g2"><div><label class="f" for="repair-start">Source interval start (seconds)</label><input id="repair-start" type="number" min="0" step=".01" value="0"></div><div><label class="f" for="repair-end">Source interval end (seconds)</label><input id="repair-end" type="number" min=".15" step=".01" value="2"></div></div>`}<label class="f" for="repair-recipe">Repair recipe</label><select id="repair-recipe">${recipes.map(r=>`<option value="${r.id}">${esc(r.name)} · v${r.version}${r.fps?' · up to '+((r.max_frames-1)/r.fps).toFixed(2)+'s':''}</option>`).join('')}</select><label class="f" for="repair-prompt">Repair direction</label><textarea id="repair-prompt" placeholder="${image?'Correct the hand while preserving the character, outfit and lighting.':'Keep the composition; make the movement between these frames smooth.'}" oninput="REPAIR.dirty=true"></textarea><label class="f" for="repair-seed">Seed</label><input id="repair-seed" type="number" min="1" value="1"><p class="sv-help">${recipes.length?'The recipe is checked against enabled servers before queuing.':'No compatible repair recipe. Create or import one in Generation lab.'}</p><div id="creative-live-results"></div>`, '<button class="btn" onclick="closeModal()">Close</button><button class="btn pri" id="repair-queue">Queue repair candidate</button>',{beforeClose:()=>!REPAIR?.busy&&(!REPAIR?.dirty||confirm('Discard this repair draft?')),onClose:()=>{REPAIR=null}});
 if(image){const img=$('#repair-image'),canvas=$('#repair-mask');const ready=()=>{if(!REPAIR||REPAIR.tid!==source.id)return;if(img.naturalWidth>4096||img.naturalHeight>4096){creativeMessage('Paint repairs on images up to 4096 pixels per side, or upload a mask PNG.',true);return}canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;REPAIR.canvas=canvas};img.onload=ready;if(img.complete)ready();let drawing=false;const paint=e=>{if(!drawing||!REPAIR.canvas)return;const r=canvas.getBoundingClientRect(),g=canvas.getContext('2d');g.fillStyle='#fff';g.beginPath();g.arc((e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height,+$('#repair-brush').value/2,0,Math.PI*2);g.fill();REPAIR.dirty=true};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);paint(e)};canvas.onpointermove=paint;canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=canvas.onpointerup}
 else{$('#repair-video').onloadedmetadata=()=>{$('#repair-end').value=Math.min(2,$('#repair-video').duration).toFixed(2)}}
 $('#repair-queue').disabled=!recipes.length;$('#repair-queue').onclick=e=>creativeBusy(e.currentTarget,queueRepair);refreshCreativeResults();
}
function changeRepairSource(sid,tid){if(REPAIR?.dirty&&!confirm('Discard the current repair draft?')){$('#repair-source').value=REPAIR.tid;return}REPAIR.dirty=false;closeModal();openRepair(sid,tid)}
function clearRepairMask(){if(REPAIR?.canvas){REPAIR.canvas.getContext('2d').clearRect(0,0,REPAIR.canvas.width,REPAIR.canvas.height);REPAIR.dirty=true}}
function fillRepairMask(){if(REPAIR?.canvas){const g=REPAIR.canvas.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,REPAIR.canvas.width,REPAIR.canvas.height);REPAIR.dirty=true}}
function repairMaskFile(){const original=REPAIR.canvas;if(!original)throw Error('Wait for the repair image to load, or upload a mask.');const canvas=document.createElement('canvas');canvas.width=original.width;canvas.height=original.height;const g=canvas.getContext('2d'),pixels=original.getContext('2d').getImageData(0,0,canvas.width,canvas.height);let painted=false;for(let i=0;i<pixels.data.length;i+=4){const alpha=pixels.data[i+3];if(alpha)painted=true;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=255;pixels.data[i+3]=255-alpha}if(!painted)throw Error('Paint the area to repair first.');g.putImageData(pixels,0,0);return{name:'repair-mask.png',data:canvas.toDataURL('image/png')}}
async function queueRepair(){REPAIR.busy=true;try{const b={shot_id:REPAIR.sid,take_id:REPAIR.tid,source_token:REPAIR.token,recipe_id:$('#repair-recipe').value,prompt:$('#repair-prompt').value,seed:+$('#repair-seed').value};if(REPAIR.image)b.mask=$('#repair-mask-file').files[0]?await readFile($('#repair-mask-file').files[0]):repairMaskFile();else{b.start=+$('#repair-start').value;b.end=+$('#repair-end').value}const r=await creativePost('repair',b);if(r.ok!==false){REPAIR.dirty=false;creativeMessage('Repair candidate queued. The selected source is preserved.');refreshCreativeResults()}}finally{if(REPAIR)REPAIR.busy=false}}

// Performance editing uses an explicit base-audio token. Phrase candidates never auto-replace it.
async function openPerformance(sid,lineId){
 if(typeof SHOT_VOICE_EDIT!=='undefined'&&SHOT_VOICE_EDIT){if(shotVoiceDirty())return toast('Save dialogue before opening its performance editor.',true);if(!closeModal())return}
 const r=await creativePost('performance',{shot_id:sid,line_id:lineId});if(r.ok===false)return;
 PERFORMANCE={...r,sid,dirty:false,busy:false,selected:new Set(),source:r.source};
 const terms=creativeState().pronunciations[r.character_id]||{};
 creativeModal('Dialogue performance',`<p><b>${esc(S.assets.find(a=>a.id===r.character_id)?.name||'Recorded dialogue')}</b> · ${esc(r.text)}</p><audio id="performance-audio" controls src="${esc(r.audio_url)}" aria-label="Selected line performance"></audio><canvas id="performance-waveform" width="960" height="100" role="img" aria-label="Waveform of the selected dialogue performance"></canvas><p id="performance-source" class="${r.source==='estimated'?'warn-t':'muted'}">${r.source==='estimated'?'Estimated word timing from audio energy. Review or import alignment before choosing a phrase; these are not forced-alignment results.':r.source==='imported'?'Imported word timings.':r.source==='speech'?'Speech-based word timings; review against the recording.':'Manually reviewed/edited word timings.'}</p><div class="toolbar"><button class="btn sm" onclick="startSpeechAlignment(this)">Align spoken words locally</button><button class="btn sm" id="performance-import">Import word timings…</button><button class="btn sm" id="performance-preview">Preview selected phrase</button><span id="performance-range" class="muted">Select contiguous words for a phrase retake.</span></div><div id="speech-alignment" role="status"></div><div class="performance-word-heading"><span>Retake</span><span>Spoken word</span><span>Start (s)</span><span>End (s)</span></div><div class="performance-words" id="performance-words">${r.words.map((w,i)=>`<div class="performance-word" role="group" aria-label="Word ${i+1}: ${esc(w.text)}"><input type="checkbox" aria-label="Include word ${i+1} in retake" onchange="selectPerformanceWord(${i},this.checked)"><b>${esc(w.text)}</b><input id="performance-start-${i}" type="number" min="0" max="${r.seconds}" step=".01" value="${w.start}" aria-label="Word ${i+1} start in seconds" oninput="performanceEdited()"><input id="performance-end-${i}" type="number" min="0" max="${r.seconds}" step=".01" value="${w.end}" aria-label="Word ${i+1} end in seconds" oninput="performanceEdited()"></div>`).join('')}</div><div class="g2"><div><label class="f" for="performance-lead">Place line later: lead-in silence (seconds)</label><input id="performance-lead" type="number" min="0" max="30" step=".05" value="${r.lead_in}" oninput="PERFORMANCE.dirty=true"></div><div><label class="f" for="performance-pause">Pause after line (seconds)</label><input id="performance-pause" type="number" min="0" max="30" step=".05" value="${r.pause_after}" oninput="PERFORMANCE.dirty=true"></div></div><details class="creative-fieldset"><summary>Character pronunciation dictionary</summary><p class="sv-help">One pair per line: <code>Tobi = Toh bee</code>. The generated speech uses the spoken spelling; the saved script stays unchanged.</p><textarea id="performance-pronunciations" aria-label="Pronunciation pairs" ${r.character_id?'':'disabled'} oninput="PERFORMANCE.dirty=true">${esc(Object.entries(terms).map(([word,spoken])=>word+' = '+spoken).join('\n'))}</textarea></details><div class="creative-section-heading"><h3>Phrase retakes</h3><label class="check"><input id="performance-fit" type="checkbox" checked> Fit replacement to the original interval</label></div><p class="sv-help">Save reviewed timings, select a word range and queue a new performance. Preview it before applying. Fitting retains the interval length; turning it off ripples later audio.</p><div id="performance-candidates"></div>`, '<button class="btn" onclick="closeModal()">Close</button><button class="btn" id="performance-queue">Queue phrase retake</button><button class="btn pri" id="performance-save">Save timing & pronunciation</button>',{beforeClose:()=>!PERFORMANCE?.busy&&(!PERFORMANCE?.dirty||confirm('Discard unsaved performance edits?')),onClose:()=>{const audio=$('#performance-audio');audio?.pause();PERFORMANCE?.preview?.pause();PERFORMANCE=null}});
 const canvas=$('#performance-waveform'),g=canvas.getContext('2d');g.fillStyle='#f2f4f7';g.fillRect(0,0,canvas.width,canvas.height);g.strokeStyle='#2f6fa8';g.beginPath();r.peaks.forEach((v,i)=>{const x=i/r.peaks.length*canvas.width;g.moveTo(x,50-v*46);g.lineTo(x,50+v*46)});g.stroke();
 $('#performance-save').onclick=e=>creativeBusy(e.currentTarget,savePerformance);
 $('#performance-queue').onclick=e=>creativeBusy(e.currentTarget,async()=>{if(PERFORMANCE.dirty)return creativeMessage('Save and review word timings before generating a phrase.',true);if(!PERFORMANCE.selected.size)return creativeMessage('Choose words to retake.',true);const indexes=[...PERFORMANCE.selected].sort((a,b)=>a-b);PERFORMANCE.busy=true;try{const result=await creativePost('phrase_generate',{shot_id:sid,line_id:lineId,token:PERFORMANCE.token,first:indexes[0],last:indexes.at(-1)});if(result.ok!==false)creativeMessage('Phrase retake queued. Your selected performance is unchanged.')}finally{if(PERFORMANCE)PERFORMANCE.busy=false}});
 $('#performance-preview').onclick=()=>{if(!PERFORMANCE.selected.size)return creativeMessage('Select words to preview.',true);const indexes=[...PERFORMANCE.selected].sort((a,b)=>a-b),words=performanceWords(),audio=$('#performance-audio');audio.currentTime=words[indexes[0]].start;audio.ontimeupdate=()=>{if(audio.currentTime>=words[indexes.at(-1)].end)audio.pause()};audio.play().catch(()=>creativeMessage('Could not play this audio.',true))};
 $('#performance-import').onclick=()=>pick('.json',file=>{try{const raw=JSON.parse(atob(file.data.split(',').at(-1))),words=Array.isArray(raw)?raw:raw.words||raw.segments?.flatMap(s=>s.words||[]);importPerformanceWords(words)}catch(e){creativeMessage('Choose a JSON word list with text, start and end values. '+e.message,true)}});refreshPerformanceCandidates();
}
function performanceWords(){return PERFORMANCE.words.map((w,i)=>({text:w.text,start:+$('#performance-start-'+i).value,end:+$('#performance-end-'+i).value}))}
function performanceEdited(){PERFORMANCE.dirty=true;PERFORMANCE.source='edited';$('#performance-source').textContent='Manually edited timings; save to apply.';$('#performance-source').className='muted'}
function selectPerformanceWord(index,on){on?PERFORMANCE.selected.add(index):PERFORMANCE.selected.delete(index);const indexes=[...PERFORMANCE.selected].sort((a,b)=>a-b);$('#performance-range').textContent=indexes.length?'Retake words '+(indexes[0]+1)+'–'+(indexes.at(-1)+1)+' (including words between them).':'Select words to retake.'}
function importPerformanceWords(words){if(!Array.isArray(words)||words.length!==PERFORMANCE.words.length)throw Error('The list must match the saved words in order.');const norm=s=>s.toLocaleLowerCase().replace(/[^\p{L}\p{N}]/gu,'');const clean=words.map((w,i)=>{if(norm(w.text??w.word??'')!==norm(PERFORMANCE.words[i].text))throw Error('Word '+(i+1)+' does not match the script.');const start=+w.start,end=+w.end;if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>PERFORMANCE.seconds)throw Error('Invalid word range.');return{start,end}});clean.forEach((w,i)=>{$('#performance-start-'+i).value=w.start;$('#performance-end-'+i).value=w.end});PERFORMANCE.source='imported';PERFORMANCE.dirty=true;$('#performance-source').textContent='Imported timings ready for review and save.';$('#performance-source').className='muted'}
function pronunciationPairs(value){const terms={};for(const raw of value.split('\n')){if(!raw.trim())continue;const at=raw.indexOf('=');if(at<1||!raw.slice(at+1).trim())throw Error('Use word = spoken spelling, one pair per line.');terms[raw.slice(0,at).trim()]=raw.slice(at+1).trim()}return terms}
async function savePerformance(){const p=PERFORMANCE;const terms=pronunciationPairs($('#performance-pronunciations').value),words=performanceWords();p.busy=true;try{const result=await creativePost('performance_save',{shot_id:p.sid,line_id:p.line_id,token:p.token,words,source:p.source,terms,lead_in:+$('#performance-lead').value,pause_after:+$('#performance-pause').value});if(result.ok!==false){p.token=result.token;p.words=words;p.dirty=false;creativeMessage('Performance timing and pronunciation saved.')}}finally{if(PERFORMANCE)PERFORMANCE.busy=false}}
function refreshPerformanceCandidates(){if(!PERFORMANCE||!$('#performance-candidates'))return;const candidates=(creativeState().phrase_takes||[]).filter(t=>t.shot_id===PERFORMANCE.sid&&t.line_id===PERFORMANCE.line_id);const html=candidates.map(t=>`<div class="performance-candidate" data-creative-key="${t.id}"><div><b>${esc(t.phrase)}</b><span class="muted"> · ${t.seconds.toFixed(2)}s</span><audio controls preload="none" src="/media/${esc(t.path)}" aria-label="Phrase retake preview"></audio></div><button class="btn sm" onclick="applyPerformanceTake(${jsq(t.id)},this)">Apply phrase…</button></div>`).join('')||'<p class="muted">No phrase retakes yet. Results appear here automatically.</p>';const box=$('#performance-candidates');updateCreativeCandidates(box,html)}
async function applyPerformanceTake(id,button){if(PERFORMANCE.dirty)return creativeMessage('Save timing changes before applying a retake.',true);if(!confirm('Replace this phrase in the selected performance? A full-line take and history checkpoint preserve the original.'))return;const p=PERFORMANCE;await creativeBusy(button,async()=>{p.busy=true;try{const r=await creativePost('performance_apply',{shot_id:p.sid,line_id:p.line_id,take_id:id,fit:$('#performance-fit').checked});if(r.ok!==false){p.dirty=false;p.busy=false;closeCreativeSaved();await openPerformance(p.sid,p.line_id)}}finally{if(PERFORMANCE)PERFORMANCE.busy=false}})}

// Recipe authoring exposes a bounded list of controls; ordinary creative flows do not show graph internals.
function renderGenerationLab(){
 const c=creativeState();if(!S.shots.some(s=>s.id===CREATIVE_SHOT))CREATIVE_SHOT=S.shots[0]?.id||null;
 if(document.activeElement?.closest('#t-lab')&&['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;
 if(same('creative-lab',[c.recipes,c.assignments,c.runs,c.benchmarks,S.shots.map(s=>[s.id,s.seq,s.scene,s.keyframe_take,s.clip_take,s.final_take,s.cont,s.lines.map(l=>l.audio)]),CREATIVE_SHOT]))return;
 const shot=S.shots.find(s=>s.id===CREATIVE_SHOT);
 $('#t-lab').innerHTML=`<div class="toolbar"><button class="btn pri" onclick="editGenerationRecipe()">Create recipe</button><label for="lab-shot">Shot</label><select id="lab-shot" class="creative-select" onchange="CREATIVE_SHOT=+this.value;delete SIG['creative-lab'];this.blur();renderGenerationLab()">${S.shots.map(s=>`<option value="${s.id}" ${s.id===CREATIVE_SHOT?'selected':''}>${pad(s.seq)} · ${esc(s.scene)}</option>`).join('')}</select><button class="btn" ${shot?'':'disabled'} onclick="assignShotRecipe(CREATIVE_SHOT)">Shot recipe settings</button></div><p class="muted">Recipe versions freeze their API workflow and controls for each queued job. Server updates remain manual. Compare a small batch before adopting settings.</p><div class="creative-grid">${c.recipes.map(r=>`<article class="creative-card"><div class="creative-card-body"><span class="eyebrow">${esc(r.stage)} · V${r.version} · ${r.nodes} nodes</span><h3>${esc(r.name)}</h3><p>${r.purpose==='generation'?'Generation preset':r.purpose==='image_repair'?'Masked image repair':'Boundary-guided video interval repair'}</p><p class="sv-help">${esc(r.requirements||'Run a compatibility check on your enabled servers.')}</p><div class="toolbar"><button class="btn sm" onclick="checkGenerationRecipe(${jsq(r.id)},this)">Check servers</button>${r.purpose==='generation'?`<button class="btn sm" ${shot?'':'disabled'} onclick="openExperiment(${jsq(r.id)},CREATIVE_SHOT)">Compare variants</button>`:''}<button class="btn sm ghost" onclick="editGenerationRecipe(${jsq(r.id)})">New version</button></div><details><summary>Export recipe and API workflow</summary><div class="toolbar"><button class="btn sm" onclick="exportGenerationRecipe(${jsq(r.id)},false)">Recipe package</button><button class="btn sm" onclick="exportGenerationRecipe(${jsq(r.id)},true)">API workflow</button></div></details></div></article>`).join('')}</div><div class="creative-section-heading"><h2>Measured runs</h2><span class="muted">Recent completed job wall time, including collection; failed runs excluded.</span></div><div class="creative-benchmarks">${c.benchmarks.map(b=>{const r=c.recipes.find(r=>r.id===b.recipe_id),server=S.instances.find(i=>i.id===b.instance_id);return `<div class="creative-benchmark"><b>${esc(r?.name||'Current workflow')}</b><span>${esc(b.server_name||server?.name||'Previous server')} · ${b.samples} run(s)</span><strong>${b.median_seconds.toFixed(1)}s median</strong><small>${b.min_seconds.toFixed(1)}–${b.max_seconds.toFixed(1)}s range</small></div>`}).join('')||'<p class="muted">Successful recipe runs establish per-recipe, per-server timing history.</p>'}</div><div class="creative-section-heading"><h2>Shot ${shot?pad(shot.seq):'—'} · candidates and repairs</h2><button class="btn sm" onclick="go('queue')">Open render queue</button></div><div id="lab-runs" class="creative-results">${creativeRunHTML(c.runs.filter(r=>r.shot_id===CREATIVE_SHOT))}</div>`;
}
function recipeControlCandidates(workflow){const managed=new Set(['image','audio','video','file','seed','noise_seed','filename_prefix','width','height','length','ref_text','instruct']);return Object.entries(workflow).flatMap(([node,n])=>Object.entries(n.inputs||{}).filter(([field,value])=>!managed.has(field)&&!(['PROMPT','NEGATIVE','REF_TEXT'].includes(n._meta?.title?.toUpperCase())&&['text','target_text','prompt','text_g'].includes(field))&&['string','number','boolean'].includes(typeof value)).map(([field,value])=>({node,field,label:(n._meta?.title||n.class_type)+' · '+field,default:value}))) }
async function editGenerationRecipe(id){const base=creativeState().recipes.find(r=>r.id===id);let initial=base?.workflow||null;if(!initial){try{const response=await fetch('/api/workflow/keyframe');initial=await response.json()}catch(e){return toast('Could not load the workflow.',true)}}RECIPE_EDITOR={workflow:initial,base,controls:[]};
 creativeModal(base?'New recipe version':'Create generation recipe',`<p class="muted">Start from an existing stage or upload a tested ComfyUI API workflow. Only selected controls appear in shot settings; existing recipe versions are immutable.</p><div class="g2"><div><label class="f" for="recipe-name">Recipe name</label><input id="recipe-name" value="${esc(base?.name||'')}" placeholder="Dialogue close-up"></div><div><label class="f" for="recipe-stage">Stage</label><select id="recipe-stage">${['keyframe','animate','lipsync','upscale','voice'].map(s=>`<option ${s===(base?.stage||'keyframe')?'selected':''}>${s}</option>`).join('')}</select></div></div><label class="f" for="recipe-api">API workflow or recipe package (optional)</label><input type="file" id="recipe-api" accept=".json"><p id="recipe-import-status" class="muted">${base?'Cloning '+esc(base.name)+' v'+base.version:'Without a file, the current stage workflow is copied.'}</p><div class="g2"><div><label class="f" for="recipe-fps">Model fps (video)</label><input id="recipe-fps" type="number" min="0" max="120" step=".01" value="${base?.fps??S.workflows.keyframe?.fps??0}"></div><div><label class="f" for="recipe-frames">Maximum frames</label><input id="recipe-frames" type="number" min="0" max="4097" value="${base?.max_frames??S.workflows.keyframe?.max_frames??0}"></div></div><label class="f" for="recipe-purpose">Use</label><select id="recipe-purpose"><option value="generation">Generation</option><option value="image_repair">Masked image repair (SOURCE + MASK inputs)</option><option value="video_repair">Video interval repair</option></select><label class="f" for="recipe-requirements">Server requirements and installation notes</label><textarea id="recipe-requirements" placeholder="Required models/node packs and the steps you run manually on the server">${esc(base?.requirements||'')}</textarea><details open><summary>Controls exposed to the shot editor</summary><div id="recipe-controls"></div><p class="sv-help">Prompts, media inputs, seed and dimensions are supplied by the shot. Choose only parameters you want artists to adjust.</p></details>`, '<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" id="recipe-save">Save recipe version</button>',{onClose:()=>{RECIPE_EDITOR=null}});
 $('#recipe-purpose').value=base?.purpose||'generation';
 function show(){if(!RECIPE_EDITOR)return;const workflow=RECIPE_EDITOR.workflow;const selected=new Set((RECIPE_EDITOR.importedControls||base?.controls||[]).map(c=>c.node+'.'+c.field));RECIPE_EDITOR.controls=workflow?recipeControlCandidates(workflow):[];$('#recipe-controls').innerHTML=RECIPE_EDITOR.controls.map((c,i)=>`<label class="check recipe-control-choice"><input type="checkbox" data-recipe-control="${i}" ${selected.has(c.node+'.'+c.field)?'checked':''}>${esc(c.label)} <small class="muted">${esc(String(c.default).slice(0,70))}</small></label>`).join('')||'<p class="muted">Save this stage snapshot, then create a new version to expose its controls; or upload an API graph now.</p>'}
 $('#recipe-stage').onchange=async()=>{if(!base&&!$('#recipe-api').files.length){try{RECIPE_EDITOR.workflow=await(await fetch('/api/workflow/'+$('#recipe-stage').value)).json()}catch(e){RECIPE_EDITOR.workflow=null;creativeMessage('Could not load stage workflow.',true)}const stage=S.workflows[$('#recipe-stage').value];$('#recipe-fps').value=stage?.fps||0;$('#recipe-frames').value=stage?.max_frames||0;show()}};
 $('#recipe-api').onchange=async()=>{try{const raw=JSON.parse(await $('#recipe-api').files[0].text()),packageFile=raw.format==='anime-studio-recipe';RECIPE_EDITOR.workflow=packageFile?raw.recipe.workflow:raw;if(packageFile){RECIPE_EDITOR.importedControls=raw.recipe.controls||[];$('#recipe-stage').value=raw.recipe.stage;$('#recipe-fps').value=raw.recipe.fps;$('#recipe-frames').value=raw.recipe.max_frames;$('#recipe-requirements').value=raw.recipe.requirements||'';$('#recipe-name').value=raw.recipe.name||'';$('#recipe-purpose').value=raw.recipe.purpose||'generation'}if(!RECIPE_EDITOR.workflow||RECIPE_EDITOR.workflow.nodes||Object.values(RECIPE_EDITOR.workflow).some(n=>!n.class_type))throw Error('Use Workflow → Export (API), not the editable UI graph.');$('#recipe-import-status').textContent=Object.keys(RECIPE_EDITOR.workflow).length+' API nodes loaded';show()}catch(e){RECIPE_EDITOR.workflow=null;creativeMessage(e.message,true)}};show();
 $('#recipe-save').onclick=e=>creativeBusy(e.currentTarget,async()=>{const r=await creativePost('recipe_save',{base_id:base?.id,name:$('#recipe-name').value,stage:$('#recipe-stage').value,workflow:RECIPE_EDITOR.workflow||undefined,fps:+$('#recipe-fps').value,max_frames:+$('#recipe-frames').value,purpose:$('#recipe-purpose').value,requirements:$('#recipe-requirements').value,controls:[...document.querySelectorAll('[data-recipe-control]:checked')].map(el=>RECIPE_EDITOR.controls[+el.dataset.recipeControl])});if(r.ok!==false){closeCreativeSaved();toast('Saved recipe v'+r.version)}});
}
function recipeControlsHTML(recipe,values={},prefix='recipe-value'){return(recipe?.controls||[]).map((c,i)=>{const value=values[c.node+'.'+c.field]??c.default;return`<label class="f" for="${prefix}-${i}">${esc(c.label)}</label>${c.type==='boolean'?`<label class="check"><input id="${prefix}-${i}" type="checkbox" ${value?'checked':''}>Enabled</label>`:`<input id="${prefix}-${i}" type="${c.type==='number'?'number':'text'}" ${c.type==='number'?'step="any"':''} value="${esc(value)}">`}`}).join('')||'<p class="muted">This recipe uses its saved parameters. Create a new version to expose controls.</p>'}
function recipeControlValues(recipe,prefix='recipe-value'){return Object.fromEntries((recipe?.controls||[]).map((c,i)=>[c.node+'.'+c.field,c.type==='boolean'?$('#'+prefix+'-'+i).checked:c.type==='number'?+$('#'+prefix+'-'+i).value:$('#'+prefix+'-'+i).value]))}
function assignShotRecipe(sid){const shot=S.shots.find(s=>s.id===sid);if(!shot)return;let currentRecipe;
 creativeModal('Shot '+pad(shot.seq)+' · Recipe settings','<label class="f" for="assignment-stage">Generation stage</label><select id="assignment-stage">'+['keyframe','animate','lipsync','upscale','voice'].map(s=>`<option>${s}</option>`).join('')+'</select><label class="f" for="assignment-recipe">Recipe version</label><select id="assignment-recipe"></select><div id="assignment-controls"></div><p class="sv-help">This shot keeps the selected version. Changing upstream settings can make existing takes outdated. Jobs already queued retain their captured workflow and inputs.</p>','<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" id="assignment-save">Save shot recipe</button>');
 const details=()=>{currentRecipe=creativeState().recipes.find(r=>r.id===$('#assignment-recipe').value);const a=creativeState().assignments.find(a=>a.shot_id===sid&&a.stage===$('#assignment-stage').value&&a.recipe_id===currentRecipe?.id);$('#assignment-controls').innerHTML=recipeControlsHTML(currentRecipe,a?.values||{})};
 const stage=()=>{const s=$('#assignment-stage').value,assigned=creativeState().assignments.find(a=>a.shot_id===sid&&a.stage===s);$('#assignment-recipe').innerHTML='<option value="">Use current global workflow</option>'+(assigned&&!creativeState().recipes.some(r=>r.id===assigned.recipe_id)?`<option value="${assigned.recipe_id}" selected disabled>Missing recipe version — choose another</option>`:'')+creativeState().recipes.filter(r=>r.stage===s&&r.purpose==='generation').map(r=>`<option value="${r.id}" ${assigned?.recipe_id===r.id?'selected':''}>${esc(r.name)} · v${r.version}</option>`).join('');details()};$('#assignment-stage').onchange=stage;$('#assignment-recipe').onchange=details;stage();
 $('#assignment-save').onclick=e=>creativeBusy(e.currentTarget,async()=>{const r=await creativePost('recipe_assign',{shot_id:sid,stage:$('#assignment-stage').value,recipe_id:currentRecipe?.id||null,values:recipeControlValues(currentRecipe)});if(r.ok!==false){closeCreativeSaved();toast('Shot recipe saved')}});
}
function openExperiment(id,sid){const recipe=creativeState().recipes.find(r=>r.id===id),shot=S.shots.find(s=>s.id===sid);if(!recipe||!shot)return;
 creativeModal('Compare '+esc(recipe.name),`<p>Shot ${pad(shot.seq)} · v${recipe.version}. Compare up to eight variants. Nothing is selected automatically.</p>${recipe.stage==='voice'?`<label class="f" for="experiment-line">Saved dialogue line</label><select id="experiment-line">${shot.lines.map(l=>`<option value="${l.line_id}">${esc(l.text)}</option>`).join('')}</select>`:''}<div class="g2"><div><label class="f" for="experiment-seed">Starting seed</label><input id="experiment-seed" type="number" min="1" value="1"></div><div><label class="f" for="experiment-count">Candidates (1–8)</label><input id="experiment-count" type="number" min="1" max="8" value="2"></div></div><label class="check"><input id="experiment-vary-seed" type="checkbox" checked> Advance seed for each candidate</label><div class="g2"><div><label class="f" for="experiment-control">Optional parameter to compare</label><select id="experiment-control"><option value="">Same controls, different seeds</option>${recipe.controls.map(c=>`<option value="${c.node}.${c.field}">${esc(c.label)}</option>`).join('')}</select></div><div><label class="f" for="experiment-variants">Parameter values (one per line)</label><textarea id="experiment-variants" placeholder="For example: 4, 6, 8 on separate lines"></textarea></div></div><details><summary>Base recipe controls</summary>${recipeControlsHTML(recipe)}</details><p class="sv-help">Use the same seed to compare a parameter. Runs include a workflow snapshot and remain distinct from the shot's selected settings until you choose Use result.</p>`, '<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" id="experiment-run">Queue comparison</button>');
 $('#experiment-run').onclick=e=>creativeBusy(e.currentTarget,async()=>{const key=$('#experiment-control').value,control=recipe.controls.find(c=>c.node+'.'+c.field===key);let variants=Array.from({length:+$('#experiment-count').value},()=>({}));if(key){variants=$('#experiment-variants').value.split('\n').map(s=>s.trim()).filter(Boolean).map(value=>({[key]:control.type==='number'?Number(value):control.type==='boolean'?value==='true':value}));if(!variants.length)throw Error('Enter a value for each candidate.')}const r=await creativePost('experiment',{recipe_id:id,shot_id:sid,line_id:$('#experiment-line')?.value,values:recipeControlValues(recipe),variants,seed:+$('#experiment-seed').value,vary_seed:$('#experiment-vary-seed').checked});if(r.ok!==false){closeCreativeSaved();CREATIVE_SHOT=sid;delete SIG['creative-lab'];go('lab');toast('Queued '+r.queued+' comparison candidates')}});
}
async function checkGenerationRecipe(id,button){await creativeBusy(button,async()=>{const r=await creativePost('recipe_check',{recipe_id:id});if(r.ok===false)return;creativeModal('Recipe server compatibility',`<p>${esc(r.requirements||'No extra installation notes.')}</p>${r.servers.map(s=>`<div class="wf"><b>${esc(s.name)}</b><p class="${s.problems.length?'err':'ok-t'}">${s.problems.length?s.problems.map(esc).join('<br>'):'Ready for this recipe'}</p></div>`).join('')||'<p>No enabled server accepts this stage. Configure server roles in Settings.</p>'}<p class="sv-help">Checks inspect advertised node inputs. They do not install anything or prove GPU memory capacity.</p>`,'<button class="btn" onclick="closeModal()">Close</button>')})}
function downloadCreativeJSON(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportGenerationRecipe(id,apiOnly){const r=creativeState().recipes.find(r=>r.id===id);downloadCreativeJSON(r.name.replace(/[^a-z0-9_-]+/gi,'_')+'-v'+r.version+(apiOnly?'-api.json':'-recipe.json'),apiOnly?r.workflow:{format:'anime-studio-recipe',schema:1,recipe:r,node_types:[...new Set(Object.values(r.workflow).map(n=>n.class_type))]})}
function creativeTakeSelected(run,take,voice=false){const shot=S.shots.find(s=>s.id===run.shot_id);return !!shot&&(voice?shot.lines.some(l=>l.audio===take.path):[shot.keyframe_take,shot.clip_take,shot.final_take,...shot.cont].includes(take.id))}
function updateCreativeCandidates(root,html){if(root.innerHTML===html)return;const template=document.createElement('template');template.innerHTML=html;const existing=new Map([...root.children].filter(x=>x.dataset.creativeKey).map(x=>[x.dataset.creativeKey,x]));const nodes=[...template.content.children].map(fresh=>{const old=existing.get(fresh.dataset.creativeKey);return old&&old.outerHTML===fresh.outerHTML?old:fresh});root.replaceChildren(...nodes)}
function creativeRunHTML(runs){return runs.map(r=>`<article class="creative-run" data-creative-key="${r.id}"><div class="creative-run-header"><div><b>${esc(r.name)} · v${r.version}</b><span class="muted">${esc(r.kind.replaceAll('_',' '))} · ${esc(r.status)}${r.seconds!==null?' · '+r.seconds+'s':''}${r.seed?' · seed '+r.seed:''}</span></div>${['pending','running'].includes(r.status)?'<span class="pending">Results appear automatically</span>':''}</div>${r.error?`<p class="err">${esc(r.error)}</p>`:''}${Object.keys(r.values||{}).length?`<p class="sv-help">${Object.entries(r.values).map(([k,v])=>esc(k)+': '+esc(String(v))).join(' · ')}</p>`:''}<div class="creative-result-media">${(r.takes||[]).map(t=>`<div>${t.stage==='keyframe'?`<button class="creative-image-button" onclick="lb(${jsq(t.url)})"><img src="${t.url}" alt="Candidate take ${t.id}"></button>`:`<video controls preload="metadata" src="${t.url}" aria-label="Candidate take ${t.id}"></video>`}<button class="btn sm" onclick="useCreativeResult(${jsq(r.id)},${t.id},this)" ${creativeTakeSelected(r,t)?'disabled':''}>${creativeTakeSelected(r,t)?'✓ Selected':'Use result'}</button></div>`).join('')}${(r.voice_takes||[]).map(t=>`<div><audio controls preload="none" src="${t.url}" aria-label="Candidate voice take ${t.id}"></audio><button class="btn sm" onclick="useCreativeResult(${jsq(r.id)},${t.id},this)" ${creativeTakeSelected(r,t,true)?'disabled':''}>${creativeTakeSelected(r,t,true)?'✓ Selected':'Use result'}</button></div>`).join('')}${r.kind==='phrase'&&r.status==='done'?'<p class="muted">Preview and apply this retake from its dialogue Performance editor.</p>':''}</div></article>`).join('')||'<p class="muted">No creative runs for this shot yet.</p>'}
async function useCreativeResult(runId,takeId,button){await creativeBusy(button,async()=>{const r=await creativePost('use_result',{run_id:runId,take_id:takeId});if(r.ok!==false)creativeMessage('Result selected for this shot.');refreshCreativeResults()})}
function refreshCreativeResults(){if(REPAIR&&$('#creative-live-results')){const html=creativeRunHTML(creativeState().runs.filter(r=>r.shot_id===REPAIR.sid&&r.source_id===REPAIR.tid));updateCreativeCandidates($('#creative-live-results'),html)}refreshPerformanceCandidates();if(typeof refreshSpeechAlignment==='function')refreshSpeechAlignment()}
setupCreative();
